for x in pairs:
 name=x['name'];status='INCOMPATIBLE' if name in {'raha_toy','raha_movies_1'} else 'CONDITIONAL'
 qual.append({'dataset':name,'status':status,'track':'synthetic_secondary' if name in {'cars','restaurant','raha_tax','raha_hospital'} else 'published_reference_exploratory','provenance':True,'acquired':True,'integrity_verified':True,'semantic_label_validity':None,'usage_clearance':None,'alignment':x['alignment_status'],'evaluation_granularity':'cell','reason':reasons[name],'primary_accepted':False})
for x in cols:qual.append({'dataset':x['name'],'status':'CONDITIONAL','track':'published_column_value','provenance':True,'acquired':True,'integrity_verified':True,'semantic_label_validity':'publisher annotations aligned on structurally eligible subset; no new human adjudication','usage_clearance':None,'alignment':'distinct values within source column','evaluation_granularity':'column_value','reason':'Qualified technical subset; rights, conventional-control contract and independent grouping unresolved. Paper claims separate training corpora; release cannot independently verify source disjointness.','primary_accepted':False})
