 qual.append({'dataset':name,'status':'PASS_SECONDARY','track':'controlled_injection_only','provenance':True,'acquired':True,'integrity_verified':True,'semantic_label_validity':'NONE for natural DQ errors','usage_clearance':'CC BY 4.0 on official UCI page','evaluation_granularity':'cell after future logged injections','reason':'Original data acquired; outcomes are forbidden error labels. Source data not assumed pristine.','primary_accepted':False})
